def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    counts = {}
    for row in g:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    separator = next(
        r for r, row in enumerate(g)
        if len(set(row)) == 1 and row[0] != background
    )

    obj_cells = [
        (r, c) for r in range(h) for c in range(w)
        if g[r][c] not in (background, g[separator][0])
    ]
    if not obj_cells:
        return g

    top = min(r for r, c in obj_cells)
    bottom = max(r for r, c in obj_cells)
    left = min(c for r, c in obj_cells)
    shape = [(r - top, c - left, g[r][c]) for r, c in obj_cells]
    obj_height = bottom - top + 1

    for r, c in obj_cells:
        g[r][c] = background

    # Slide the object against the separator, keeping it on its original side.
    if bottom < separator:
        new_top = separator - obj_height
        marker_row = new_top - 1
    else:
        new_top = separator + 1
        marker_row = new_top + obj_height

    for dr, dc, color in shape:
        rr, cc = new_top + dr, left + dc
        if 0 <= rr < h and 0 <= cc < w:
            g[rr][cc] = color

    if 0 <= marker_row < h:
        g[marker_row] = [8] * w
    return g
